import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷二·8","description":"易小帖 - 卷二·8","frontmatter":{"title":"卷二·8","description":"易小帖 - 卷二·8"},"headers":[],"relativePath":"classics/yixiaotie/048.md","filePath":"classics/yixiaotie/048.md"}'),o={name:"classics/yixiaotie/048.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷二·8",tabindex:"-1"},[r("卷二·8 "),e("a",{class:"header-anchor",href:"#卷二·8","aria-label":"Permalink to “卷二·8”"},"​")],-1),e("p",null,"師左次者，兵禮尚右，右前左後。八陣以前衝為右，後衝為左是也。若焦弱侯雲：四乘坎之上，與兵法右背山陵，左前水澤意合，故曰左。朱楓林旁註謂：四變則互震為左。來矣鮮雲：乾先坤後，乾右坤左，故明夷六四陰也，曰左腹。豐卦九三陽也，曰右肱，此皆以兵法並乾坤為說，統不如卦例以上一爻為右，下一爻為左之簡。當然此猶尚是有據之言。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
